// Renders docs/api from schema/openapi.yaml. Event pages go under docs/api/webhooks/<version>/.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const VERSION = 'v2';
const schema = readFileSync('schema/openapi.yaml', 'utf8');
const events = [...schema.matchAll(/^  ([a-z]+\.[a-z]+):/gm)].map((m) => m[1]);
mkdirSync(`docs/api/webhooks/${VERSION}`, { recursive: true });
for (const e of events) writeFileSync(`docs/api/webhooks/${VERSION}/${e}.md`, `# ${e}\n\nSent when ${e.replace('.', ' is ')}.\n`);

